export default function Page(){return <form className="card grid gap-4 p-7" action="/api/vendor/cars" method="post" encType="multipart/form-data"><div><h2 className="text-xl font-bold">Create a vehicle draft</h2><p className="mt-1 text-sm text-[#68756f]">You can review the draft before submitting it for approval.</p></div><div className="grid gap-3 sm:grid-cols-2">{[["make","Make"],["model","Model"],["year","Year"],["price","Price (NGN)"],["mileage","Mileage (km)"],["city","City"]].map(([name,label])=><label key={name}><span className="label">{label}</span><input className="input" name={name} required type={["year","price","mileage"].includes(name)?"number":"text"}/></label>)}</div><label><span className="label">Transmission</span><select className="input" name="transmission"><option>AUTOMATIC</option><option>MANUAL</option><option>CVT</option></select></label><fieldset className="grid gap-3 rounded-xl border border-[#dfe6e1] p-4"><legend className="px-2 font-bold">Car picture</legend><label><span className="label">Image link</span><input className="input" name="imageUrl" type="url" placeholder="https://example.com/car.jpg"/></label><div className="text-center text-xs font-bold text-[#718079]">OR</div><label><span className="label">Upload image</span><input className="input" name="imageFile" type="file" accept="image/jpeg,image/png,image/webp"/><span className="mt-1 block text-xs text-[#718079]">JPEG, PNG or WebP, up to 8 MB.</span></label></fieldset><label><span className="label">Description</span><textarea className="input min-h-28" name="description" required minLength={30}/></label><button className="btn btn-dark">Save draft</button></form>}
